-- Correlation chart: ton hanya dari blok TM per BA/afd/bulan (status blok TM+PLANTED menurut INT_HEKTAR_BLOK pada bulan panen), basis yield TM = ton TM / Ha TM.
-- Hasil -> work/r_corrtm.json {"BAAFD":[9 bulan]}; tie-out: jumlah 9 bulan = r_tm.json baris Y kolom ke-5.
WITH blk AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, KODE_AFD afd, KODE_BLOK blok, DATE_TRUNC('month',BULAN)::DATE mo, MAX(IFF(MATURITY_STATUS='TM' AND KATEGORI_TANAH='PLANTED',1,0)) tm FROM PRD_DB_INTEGRATION.INT_PANEN.INT_HEKTAR_BLOK WHERE KODE_BA IN ('2121','2124','2131','2122') AND BULAN>='2026-01-01' AND BULAN<'2026-10-01' GROUP BY 1,2,3,4)
SELECT DECODE(p.KODE_BA,'2122','2131',p.KODE_BA) ba, p.KODE_AFD afd, TO_CHAR(DATE_TRUNC('month',p.TANGGAL_PANEN),'YYYY-MM') m, ROUND(SUM(IFF(b.tm=1,p.TON_AKTUAL,0)),1) tontm
FROM PRD_DB_INTEGRATION.INT_PANEN.INT_PENCAPAIAN_PRODUKSI_PANEN p LEFT JOIN blk b ON b.ba=DECODE(p.KODE_BA,'2122','2131',p.KODE_BA) AND b.afd=p.KODE_AFD AND b.blok=p.KODE_BLOK AND b.mo=DATE_TRUNC('month',p.TANGGAL_PANEN)::DATE
WHERE p.KODE_BA IN ('2121','2124','2131','2122') AND p.TANGGAL_PANEN>='2026-01-01' AND p.TANGGAL_PANEN<'2026-10-01' AND NOT (DECODE(p.KODE_BA,'2122','2131',p.KODE_BA)='2131' AND p.KODE_AFD='B')
GROUP BY 1,2,3 HAVING SUM(IFF(b.tm=1,p.TON_AKTUAL,0))>0 ORDER BY 1,2,3;
